import childProcess from "node:child_process";
import { createHash } from "node:crypto";
import { lstatSync, readFileSync, readlinkSync } from "node:fs";
import path from "node:path";

// The client subtree includes its source, packaging recipes and dependency
// locks. Ignored build outputs are regenerated by the packaging entry points.
export function clientBuildSource(root, { formal = true, expectedCommit } = {}) {
  const git = args => childProcess.execFileSync("git", args, { cwd: root, encoding: "utf8" }).trim();
  const sourceCommit = git(["rev-parse", "HEAD"]);
  if (!/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/.test(sourceCommit)) throw new Error("CLIENT_SOURCE_COMMIT_INVALID");
  const sourceDirty = Boolean(git(["status", "--porcelain=v1", "--untracked-files=all", "--ignore-submodules=none", "--", "."]));
  if (formal && sourceDirty) throw new Error("CLIENT_SOURCE_TREE_DIRTY: 正式构建需要已提交且没有未跟踪文件的客户端源码。");
  if (expectedCommit && sourceCommit !== expectedCommit) throw new Error("CLIENT_SOURCE_CHANGED_DURING_BUILD");
  return { sourceCommit: sourceDirty ? null : sourceCommit, sourceDirty };
}

// Test builds may intentionally include a reviewed dirty workspace. Record the
// precise source snapshot without claiming it is the committed release source.
export function clientTestSourceSnapshot(root) {
  const files = childProcess.execFileSync("git", ["ls-files", "-z", "--cached", "--others", "--exclude-standard", "--", "."],
    { cwd: root, encoding: "utf8" }).split("\0").filter(Boolean).sort();
  const hash = createHash("sha256");
  for (const name of [...new Set(files)]) {
    const file = path.join(root, name);
    hash.update(name).update("\0");
    try {
      const entry = lstatSync(file);
      hash.update(String(entry.mode & 0o777)).update("\0");
      hash.update(entry.isSymbolicLink() ? `symlink:${readlinkSync(file)}` : readFileSync(file));
    } catch (error) { if (error.code !== "ENOENT") throw error; hash.update("deleted"); }
    hash.update("\0");
  }
  return hash.digest("hex");
}
